import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let n = 0
    for i in 0..3 {
        for j in 0..3 { n = n + 1 }
    }
    if n == 9 { io.println("nest-ok") } else { io.println("nest-bad") }

    let z = 0
    for i in 3..3 { z = z + 1 }
    for i in 5..2 { z = z + 1 }
    if z == 0 { io.println("empty-ok") } else { io.println("empty-bad") }

    for _ in 0..2 { io.println("wild") }
    return Ok(())
}
